#include <iostream>
#include <string>
#include <map>
#include <utility>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    string s;
    cin >> n >> s;

    map<pair<int, int>, long long> frequency;
    int x = 0, y = 0;
    long long answer = 0;

    frequency[{0, 0}] = 1;

    for (char command : s) {
        if (command == 'U') ++y;
        else if (command == 'D') --y;
        else if (command == 'R') ++x;
        else if (command == 'L') --x;

        answer += frequency[{x, y}];
        ++frequency[{x, y}];
    }

    cout << answer << '\n';
    return 0;
}

