#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    string s;
    cin >> n >> s;

    vector<pair<int, int>> position(n + 1, {0, 0});

    for (int i = 0; i < n; ++i) {
        position[i + 1] = position[i];

        if (s[i] == 'U') ++position[i + 1].second;
        else if (s[i] == 'D') --position[i + 1].second;
        else if (s[i] == 'R') ++position[i + 1].first;
        else if (s[i] == 'L') --position[i + 1].first;
    }

    long long answer = 0;

    for (int i = 0; i <= n; ++i) {
        for (int j = i + 1; j <= n; ++j) {
            if (position[i] == position[j]) {
                ++answer;
            }
        }
    }

    cout << answer << '\n';
    return 0;
}
